const TRANSLATIONS = Object.fromEntries(Object.entries(ROWS).map(([phrase, values]) => [
  phrase, Object.fromEntries(LOCALES.map((locale, index) => [locale, values[index]])),
]))

const LanguageContext = createContext({ language: 'en', setLanguage: async () => false, t: value => value })
// The Android app starts in the phone's language (until one is picked).
function deviceLanguage() {
  if (!isAndroid) return 'en'
  const wanted = String(navigator.language || '').toLowerCase()
  return APP_LANGUAGES.find(item => item.code.toLowerCase() === wanted)?.code
    || APP_LANGUAGES.find(item => item.code.split('-')[0] === wanted.split('-')[0])?.code
    || 'en'
}
function readStoredLanguage() {
  try {
    const code = localStorage.getItem('lokal-app-language')
    return APP_LANGUAGES.some(item => item.code === code) ? code : deviceLanguage()
  } catch { return deviceLanguage() }
}

export function LanguageProvider({ children }) {
  const [language, setLanguageState] = useState(readStoredLanguage)
  const userChangedRef = useRef(false)

  useEffect(() => {
    let alive = true
    Promise.resolve(api.getSettings()).then(settings => {
      if (!alive || userChangedRef.current) return
      const saved = APP_LANGUAGES.find(item => item.code === settings?.app_language)?.code
      if (saved) {
        setLanguageState(saved)
        try { localStorage.setItem('lokal-app-language', saved) } catch {}
      }
    }).catch(() => {})
    return () => { alive = false }
  }, [])

  useEffect(() => {
    if (typeof document !== 'undefined') document.documentElement.lang = language
  }, [language])

  const setLanguage = useCallback(async (code) => {
    if (!APP_LANGUAGES.some(item => item.code === code)) return false
    userChangedRef.current = true
    setLanguageState(code)
    try { localStorage.setItem('lokal-app-language', code) } catch {}
    if (typeof window !== 'undefined') window.dispatchEvent(new CustomEvent('lokal:language-changed', { detail: { language: code } }))
    try {
      const result = await api.saveSettings({ app_language: code })
      if (result?.error) throw new Error(result.error)
      return true
    } catch (error) {
      console.error('[i18n] Could not save app language:', error)
      return false
    }
  }, [])

  const t = useCallback((phrase, values = null) => {
    if (typeof phrase !== 'string') return phrase
    const translated = language === 'en' ? phrase : (TRANSLATIONS[phrase]?.[language] || phrase)
    if (!values || typeof values !== 'object') return translated
    // "{n} station|{n} stations": two forms, the first for one (`count`, else `n`).
    const count = Number(values.count ?? values.n)
    const forms = translated.includes('|') && Number.isFinite(count) ? translated.split('|') : null
    const chosen = forms && forms.length === 2 ? forms[count === 1 ? 0 : 1] : translated
    return chosen.replace(/\{([a-zA-Z0-9_]+)\}/g, (match, key) => Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : match)
  }, [language])

  return <LanguageContext.Provider value={{ language, setLanguage, t }}>{children}</LanguageContext.Provider>
}

export function useTranslation() {
  return useContext(LanguageContext)
}
